class Command(BaseCommand):
    help = "۴ سناریوی راهبردی واقعی سایپا یدک و محورهای عدم‌قطعیت را ثبت/به‌روزرسانی می‌کند."

    def handle(self, *args, **options):
        ScenarioAxes.objects.update_or_create(
            pk=1,
            defaults=dict(
                axis1_name="امکان تأمین منابع مالی",
                axis1_positive="دستیابی به منابع مالی",
                axis1_negative="عدم دستیابی به منابع مالی",
                axis2_name="وضعیت بین‌المللی",
                axis2_positive="تعاملات هدفمند بین‌المللی",
                axis2_negative="تشدید محدودیت‌های بین‌المللی",
            ),
        )
        for quadrant, d in DATA.items():
            Scenario.objects.update_or_create(
                quadrant=quadrant,
                defaults=dict(title=d["title"], narrative=d["narrative"], is_selected=d["is_selected"]),
            )
        self.stdout.write(self.style.SUCCESS("هر ۴ سناریو و محورهای عدم‌قطعیت با داده‌ی واقعی ثبت/به‌روزرسانی شد."))
